<?php require_once __DIR__.'/../config/db.php';$pdo=db();$code=strtoupper(trim($_GET['code']??''));$amount=(float)($_GET['amount']??0);if(!$code||$amount<0)json_response(['valid'=>false,'message'=>'Invalid coupon request'],400);$s=$pdo->prepare('SELECT * FROM coupons WHERE code=? AND is_active=1 AND (start_at IS NULL OR start_at<=NOW()) AND (end_at IS NULL OR end_at>=NOW()) AND (usage_limit IS NULL OR used_count<usage_limit) LIMIT 1');$s->execute([$code]);$c=$s->fetch();if(!$c)json_response(['valid'=>false,'message'=>'Coupon not found or expired']);if($amount<(float)$c['min_order'])json_response(['valid'=>false,'message'=>'Minimum order is ₹'.number_format((float)$c['min_order'],2)]);$discount=$c['type']==='percent'?$amount*((float)$c['value']/100):(float)$c['value'];if($c['max_discount']!==null)$discount=min($discount,(float)$c['max_discount']);$discount=min($discount,$amount);json_response(['valid'=>true,'code'=>$c['code'],'discount'=>round($discount,2),'message'=>'Coupon applied']);
